  statistics: ["Monitoring database activity", "https://www.postgresql.org/docs/current/monitoring-stats.html"],
  datetime: ["Date/Time types", "https://www.postgresql.org/docs/current/datatype-datetime.html"],
  concepts: ["Database concepts", "https://www.postgresql.org/docs/current/tutorial-concepts.html"],
  dataTypes: ["Data types", "https://www.postgresql.org/docs/current/datatype.html"],
  textTypes: ["Character types", "https://www.postgresql.org/docs/current/datatype-character.html"],
